        M("settings.acquisition.pageDescription", "Import mode and remote path mapping (also used to match Sonarr paths), library roots, tags, delay profiles, tag-scoped indexer restrictions, AniList auto-monitor and settings backup.", "Settings", "Body", "Subtitle summarizing everything configured on the acquisition settings page.", "clear concise copy", 220, null, ["Sonarr", "AniList"]),
