        M("settings.acquisition.importModeLabel", "Import mode", "Settings", "Label", "Label of the import mode used for this media type; it can use the default import mode.", "short form label", 20),
        M("settings.acquisition.inboxFolderLabel", "Inbox folder", "Settings", "Label", "Label of the absolute folder path that is scanned for files of this media type that Jularr did not download.", "short form label", 24),
        M("settings.acquisition.storedInJularr", "Downloads are read into Jularr's library, so there is no library folder to set.", "Settings", "Body", "Shown for Light Novels and Books, whose files are read into Jularr instead of placed in a NAS library folder.", "clear explanatory copy", 90),
        M("settings.acquisition.scanInbox", "Scan inbox", "Settings", "Button", "Imports the files currently in this media type's inbox folder.", "concise action", 18),
        M("settings.acquisition.playbackOptimizationHeading", "Lossless playback optimization", "Settings", "Heading", "Heading of the panel for the post-import step that rewraps video into a more browser-friendly container without re-encoding.", "clear heading", 34),
        M("settings.acquisition.playbackOptimizationDescription", "After an import, rewraps a video into MP4 without re-encoding when that lets more browsers play it directly. Files whose subtitles, fonts or audio MP4 cannot keep unchanged stay as they are.", "Settings", "Body", "Explains that the optimization only changes the container, never the quality, and leaves files that would lose anything untouched.", "clear technical copy", 220, null, ["MP4"]),
        M("settings.acquisition.playbackOptimizationLabel", "After import", "Settings", "Label", "Form label for choosing whether imported video is optimized for browser Direct Play.", "short form label", 20),
