        M("settings.acquisition.remotePathMappingHeading", "Remote path mapping", "Settings", "Heading", "Heading of the remote path mapping panel.", "clear heading", 24),
        M("settings.acquisition.remotePathMappingDescription", "Maps a path prefix as reported by the download client to the path Jularr sees under its own mounts, separately for each media type. Anime mappings also translate Sonarr's series/episode/queue paths, so Sonarr ↔ Jularr path matching keeps working even when the two containers mount storage differently.", "Settings", "Body", "Explains that remote path mappings are set per media type and how the Anime mappings also keep Sonarr paths matched to Jularr's own mounts.", "clear technical copy", 320, null, ["Sonarr", "Jularr"]),
        M("settings.acquisition.remotePrefixColumn", "Remote path reported by Sonarr or SABnzbd", "Settings", "Label", "Table column header and form label for the remote side of a path mapping: the path prefix as the download client or Sonarr reports it, which Jularr may not see under the same name.", "short column header", 44, null, ["Sonarr", "SABnzbd"]),
        M("settings.acquisition.localPrefixColumn", "Local path visible to Jularr", "Settings", "Label", "Table column header and form label for the local side of a path mapping: the folder as the Jularr container sees it.", "short column header", 34, null, ["Jularr"]),
