        M("settings.anilist.safety.heading", "Safe progress sync", "Settings", "Heading", "Heading of the section explaining AniList sync safety guarantees.", "clear heading", 26, null, ["AniList"]),
        M("settings.anilist.safety.badge", "Progress only", "Settings", "Label", "Badge clarifying that only progress is ever synced to AniList.", "short label", 18, null, ["AniList"]),
        M("settings.anilist.safety.paragraph1", "Jularr reads the current remote list entry again immediately before every write. Progress can only move upward and only for an existing CURRENT (Watching) list entry with an unambiguous AniList match. Multi-season local groupings are blocked rather than guessed. The final episode is intentionally not synced because AniList may also change completion status/date. Every write gets a local pre-write snapshot with the local Jularr profile ID under /data/integrations.", "Settings", "Body", "Explains the pre-write re-read, forward-only, and snapshot safety guarantees of AniList progress sync.", "clear technical reassurance", 480, null, ["Jularr", "AniList", "CURRENT"]),
        M("settings.anilist.safety.paragraph2", "Automatic sync uses exactly the same checks as the Sync button. Works whose AniList mapping is ambiguous or waiting for review are never written, AniList progress that is already ahead is left alone, and failed requests are retried with increasing delays, honoring AniList's rate limit.", "Settings", "Body", "Explains that automatic sync shares the same safety checks as manual sync and respects AniList rate limits.", "clear technical reassurance", 300, null, ["AniList"]),
        M("settings.anilist.safety.paragraph3", "Jularr does not automatically create list entries, change list status, mark entries completed, change scores, notes, repeat counts, priorities, privacy, custom lists or dates.", "Settings", "Body", "Lists the AniList fields and actions that automatic sync never touches.", "clear reassuring copy", 200, null, ["Jularr", "AniList"]),
        M("settings.anilist.syncMode.off", "Off", "Settings", "Option", "Automatic AniList sync mode that never writes progress automatically.", "short option label", 8, null, ["AniList"]),
